static void cleanup_tiff_handles_and_temp_files() {
    std::vector<void*> closed_tiff_ptrs;
    for (uint32_t t = 0; t < (uint32_t)HT__COUNT; ++t) {
        if (!is_tiff_handle_type(t)) continue;
        HandleTable& tab = g_tables[t];
        for (uint32_t i = 1; i <= tab.count; ++i) {
            if (!tab.valid[i]) continue;
            void* ptr = tab.handles[i];
            if (!ptr) {
                tab.valid[i] = false;
                continue;
            }
            if (std::find(closed_tiff_ptrs.begin(), closed_tiff_ptrs.end(), ptr) == closed_tiff_ptrs.end()) {
                TIFFClose((TIFF*)ptr);
                closed_tiff_ptrs.push_back(ptr);
            }
            tab.valid[i] = false;
            tab.handles[i] = nullptr;
        }
    }

    std::vector<void*> freed_open_opts;
    HandleTable& open_opts_tab = g_tables[HT_struct_TIFFOpenOptions];
    for (uint32_t i = 1; i <= open_opts_tab.count; ++i) {
        if (!open_opts_tab.valid[i]) continue;
        void* ptr = open_opts_tab.handles[i];
        if (!ptr) {
            open_opts_tab.valid[i] = false;
            continue;
        }
        if (std::find(freed_open_opts.begin(), freed_open_opts.end(), ptr) == freed_open_opts.end()) {
            TIFFOpenOptionsFree((TIFFOpenOptions*)ptr);
            freed_open_opts.push_back(ptr);
        }
        open_opts_tab.valid[i] = false;
        open_opts_tab.handles[i] = nullptr;
    }

    std::vector<void*> freed_heap_ptrs;
    for (void* ptr : g_auto_heap_ptrs) {
        if (!ptr) continue;
        if (std::find(freed_heap_ptrs.begin(), freed_heap_ptrs.end(), ptr) == freed_heap_ptrs.end()) {
            std::free(ptr);
            freed_heap_ptrs.push_back(ptr);
        }
    }
    g_auto_heap_ptrs.clear();

    if (!freed_heap_ptrs.empty()) {
        for (uint32_t t = 0; t < (uint32_t)HT__COUNT; ++t) {
            HandleTable& tab = g_tables[t];
            for (uint32_t i = 1; i <= tab.count; ++i) {
                void* ptr = tab.handles[i];
                if (!ptr) continue;
                if (std::find(freed_heap_ptrs.begin(), freed_heap_ptrs.end(), ptr) != freed_heap_ptrs.end()) {
                    tab.valid[i] = false;
                    tab.handles[i] = nullptr;
                }
            }
        }
    }

    for (const std::string& path : g_auto_tiff_paths) {
        unlink(path.c_str());
    }
    g_auto_tiff_paths.clear();
}

